const __assert = require('node:assert');
const describe = (name, fn) => { fn(); };
const test = (name, fn) => { try { fn(); } catch (e) { e.message = name + ': ' + e.message; throw e; } };
const it = test;
const expect = (actual) => {
  const fail = (m) => { throw new __assert.AssertionError({ message: m }); };
  const m = {
    toBe: (e) => { if (!Object.is(actual, e)) fail('toBe ' + String(actual) + ' vs ' + String(e)); },
    toEqual: (e) => __assert.deepStrictEqual(actual, e),
    toStrictEqual: (e) => __assert.deepStrictEqual(actual, e),
    toBeTruthy: () => { if (!actual) fail('toBeTruthy'); },
    toBeFalsy: () => { if (actual) fail('toBeFalsy'); },
    toBeNull: () => { if (actual !== null) fail('toBeNull'); },
    toBeUndefined: () => { if (actual !== undefined) fail('toBeUndefined'); },
    toBeDefined: () => { if (actual === undefined) fail('toBeDefined'); },
    toBeNaN: () => { if (!Number.isNaN(actual)) fail('toBeNaN'); },
    toBeCloseTo: (e, d = 2) => { if (!(Math.abs(actual - e) < Math.pow(10, -d) / 2)) fail('toBeCloseTo'); },
    toBeGreaterThan: (e) => { if (!(actual > e)) fail('toBeGreaterThan'); },
    toBeGreaterThanOrEqual: (e) => { if (!(actual >= e)) fail('toBeGreaterThanOrEqual'); },
    toBeLessThan: (e) => { if (!(actual < e)) fail('toBeLessThan'); },
    toBeLessThanOrEqual: (e) => { if (!(actual <= e)) fail('toBeLessThanOrEqual'); },
    toContain: (e) => { if (!(actual != null && typeof actual.includes === 'function' && actual.includes(e))) fail('toContain'); },
    toHaveLength: (n) => { if (!(actual != null && actual.length === n)) fail('toHaveLength'); },
    toMatch: (p) => { if (!(typeof p === 'string' ? String(actual).includes(p) : p.test(actual))) fail('toMatch'); },
    toThrow: (arg) => {
      let thrown = null;
      try { actual(); } catch (err) { thrown = err; }
      if (thrown === null) fail('toThrow: nothing was thrown');
      if (arg instanceof Error) { if (thrown.message !== arg.message) fail('toThrow: message'); }
      else if (typeof arg === 'string') { if (!String(thrown.message).includes(arg)) fail('toThrow: message'); }
      else if (arg instanceof RegExp) { if (!arg.test(String(thrown.message))) fail('toThrow: message'); }
    },
  };
  m.not = {};
  for (const k of Object.keys(m)) {
    if (k === 'not') continue;
    m.not[k] = (...a) => { let ok = false; try { m[k](...a); } catch (err) { ok = true; } if (!ok) fail('not.' + k); };
  }
  return m;
};

describe('Sgf Parsing', () => {
  test('empty input', () => {
    expect(() => parse('')).toThrow('tree missing');
  });

  test('tree with no nodes', () => {
    expect(() => parse('()')).toThrow('tree with no nodes');
  });

  test('node without tree', () => {
    expect(() => parse(';')).toThrow('tree missing');
  });

  test('node without properties', () => {
    expect(parse('(;)')).toEqual({ properties: {}, children: [] });
  });

  test('single node tree', () => {
    expect(parse('(;A[B])')).toEqual({
      properties: { A: ['B'] },
      children: [],
    });
  });

  test('multiple properties', () => {
    expect(parse('(;A[b]C[d])')).toEqual({
      properties: { A: ['b'], C: ['d'] },
      children: [],
    });
  });

  test('properties without delimiter', () => {
    expect(() => parse('(;A)')).toThrow('properties without delimiter');
  });

  test('all lowercase property', () => {
    expect(() => parse('(;a[b])')).toThrow('property must be in uppercase');
  });

  test('upper and lowercase property', () => {
    expect(() => parse('(;Aa[b])')).toThrow('property must be in uppercase');
  });

  test('two nodes', () => {
    expect(parse('(;A[B];B[C])')).toEqual({
      properties: { A: ['B'] },
      children: [
        {
          properties: { B: ['C'] },
          children: [],
        },
      ],
    });
  });

  test('two child trees', () => {
    expect(parse('(;A[B](;B[C])(;C[D]))')).toEqual({
      properties: { A: ['B'] },
      children: [
        {
          properties: { B: ['C'] },
          children: [],
        },
        {
          properties: { C: ['D'] },
          children: [],
        },
      ],
    });
  });

  test('multiple property values', () => {
    expect(parse('(;A[b][c][d])')).toEqual({
      properties: { A: ['b', 'c', 'd'] },
      children: [],
    });
  });

  test('within property values, whitespace characters such as tab are converted to spaces', () => {
    expect(parse('(;A[hello\t\tworld])')).toEqual({
      properties: { A: ['hello  world'] },
      children: [],
    });
  });

  test('within property values, newlines remain as newlines', () => {
    expect(parse('(;A[hello\n\nworld])')).toEqual({
      properties: { A: ['hello\n\nworld'] },
      children: [],
    });
  });

  test('escaped closing bracket within property value becomes just a closing bracket', () => {
    expect(parse('(;A[\\]])')).toEqual({
      properties: { A: [']'] },
      children: [],
    });
  });

  test('escaped backslash in property value becomes just a backslash', () => {
    expect(parse('(;A[\\\\])')).toEqual({
      properties: { A: ['\\'] },
      children: [],
    });
  });

  test("opening bracket within property value doesn't need to be escaped", () => {
    expect(parse('(;A[b[c])')).toEqual({
      properties: { A: ['b[c'] },
      children: [],
    });
  });

  test("semicolon in property value doesn't need to be escaped", () => {
    expect(parse('(;A[a;b])')).toEqual({
      properties: { A: ['a;b'] },
      children: [],
    });
  });

  test("parentheses in property value don't need to be escaped", () => {
    expect(parse('(;A[a(b])')).toEqual({
      properties: { A: ['a(b'] },
      children: [],
    });
  });

  test('escaped tab in property value is converted to space', () => {
    expect(parse('(;A[\\\t])')).toEqual({
      properties: { A: [' '] },
      children: [],
    });
  });

  test('escaped newline in property value is converted to nothing at all', () => {
    expect(parse('(;A[\\\n])')).toEqual({
      properties: { A: [''] },
      children: [],
    });
  });

  test('escaped t and n in property value are just letters, not whitespace', () => {
    expect(parse('(;A[\\t][\\n])')).toEqual({
      properties: { A: ['t', 'n'] },
      children: [],
    });
  });

  test('mixing various kinds of whitespace and escaped characters in property value', () => {
    expect(parse('(;A[\\]b\nc\\\nd\t\te\\\\ \\\n\\]])')).toEqual({
      properties: { A: [']b\ncd  e\\ ]'] },
      children: [],
    });
  });
});
